mapper.select:
select b.fc_id,b.function_id,b.fc_code,tl.fc_name,tl.fc_desc,b.fc_display_flag,b.fc_editable_flag,b.parent_id,b.vs_id,b.fc_type
from sys_function_column_b b
left join sys_function_column_tl tl on tl.fc_id = b.fc_id and tl.language = #{language}
where b.parent_id in

	#{blockId}

order by b.fc_id

select b.fc_id,b.function_id,b.fc_code,tl.fc_name,tl.fc_desc,b.fc_display_flag,b.fc_editable_flag,b.parent_id,b.vs_id,b.fc_type
from sys_function_column_b b
left join sys_function_column_tl tl on tl.fc_id = b.fc_id and tl.language = #{language}
where b.parent_id is null and b.fc_code = #{blockCode}

select b.fc_id,b.function_id,b.fc_code,tl.fc_name,tl.fc_desc,b.fc_display_flag,b.fc_editable_flag,b.parent_id,b.vs_id,b.fc_type
from sys_function_column_b b
left join sys_function_column_tl tl on tl.fc_id = b.fc_id and tl.language = #{language}
where b.parent_id = #{blockId} and b.fc_code = #{columnCode}

mapper.update:
update sys_function_column_tl
fc_name = #{fcName}, fc_desc = #{fcDesc}, last_update_by = #{lastUpdateBy}, last_update_date = #{lastUpdateDate}, last_update_login = #{lastUpdateLogin}
where fc_id = #{fcId} and language = #{language}

update sys_function_column_b
fc_code = #{fcCode}, fc_display_flag = #{fcDisplayFlag}, fc_editable_flag = #{fcEditableFlag}, vs_id = #{vsId}, fc_type = #{fcType}, last_update_by = #{lastUpdateBy}, last_update_date = #{lastUpdateDate}, last_update_login = #{lastUpdateLogin}
where fc_id = #{fcId}

